library ieee; use ieee.std_logic_1164.all; use ieee.numeric_std.all;
entity soqpsk_linear_interp is port(clk,reset,valid:in std_logic; alpha:in unsigned(7 downto 0); i_in,q_in:in signed(31 downto 0); i_out,q_out:out signed(31 downto 0); valid_out:out std_logic); end;
architecture rtl of soqpsk_linear_interp is signal pi,pq:signed(31 downto 0):=(others=>'0'); begin process(clk) variable a,b:signed(39 downto 0); begin if rising_edge(clk) then valid_out<='0'; if reset='1' then pi<=(others=>'0');pq<=(others=>'0'); else if valid='1' then a:=pi*to_signed(255-to_integer(alpha),8)+i_in*to_signed(to_integer(alpha),8); b:=pq*to_signed(255-to_integer(alpha),8)+q_in*to_signed(to_integer(alpha),8); i_out<=resize(shift_right(a,8),32);q_out<=resize(shift_right(b,8),32);pi<=i_in;pq<=q_in;valid_out<='1'; end if; end if; end if; end process; end;
